--
-- Table structure for table `bus_chat_conversation`
--

DROP TABLE IF EXISTS `bus_chat_conversation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bus_chat_conversation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '会话ID（按标的线程）',
  `a_user_id` bigint NOT NULL COMMENT '参与者A用户ID（小的那个）',
  `b_user_id` bigint NOT NULL COMMENT '参与者B用户ID（大的那个）',
  `subject_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标的类型（SUPPLY/NEED）',
  `subject_id` bigint NOT NULL COMMENT '标的ID（供应/采购ID）',
  `subject_snapshot_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '标的快照JSON（用于聊天置顶卡片）',
  `initiator_user_id` bigint DEFAULT NULL COMMENT '会话发起人userId',
  `last_msg_id` bigint DEFAULT NULL COMMENT '最后一条消息ID',
  `last_content` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '最后一条消息内容（便于列表展示）',
  `last_time` datetime(3) DEFAULT NULL COMMENT '最后活跃时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除（0否 1是）',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_chat_conv_ab_subject` (`a_user_id`,`b_user_id`,`subject_type`,`subject_id`),
  KEY `idx_chat_conv_a` (`a_user_id`),
  KEY `idx_chat_conv_b` (`b_user_id`),
  KEY `idx_chat_conv_last_time` (`last_time`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='即时聊天会话表（按标的线程）';
/*!40101 SET character_set_client = @saved_cs_client */;

