--
-- Table structure for table `bus_chat_message`
--

DROP TABLE IF EXISTS `bus_chat_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bus_chat_message` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `from_user_id` bigint NOT NULL COMMENT '发送者用户ID',
  `to_user_id` bigint NOT NULL COMMENT '接收者用户ID',
  `content` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息内容',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已读（0否 1是）',
  `read_at` datetime(3) DEFAULT NULL COMMENT '阅读时间',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除（0否 1是）',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `update_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `conversation_id` bigint DEFAULT NULL COMMENT '会话ID（bus_chat_conversation.id）',
  `msg_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'TEXT' COMMENT '消息类型（TEXT/QUOTE/SYSTEM/ATTACHMENT）',
  `payload_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '结构化负载JSON（报价卡/附件等）',
  `quote_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报价状态(OFFERED/ACCEPTED/REJECTED/EXPIRED)',
  `basis_price` decimal(10,2) DEFAULT NULL COMMENT '基差报价',
  `contract_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '期货合约代码',
  PRIMARY KEY (`id`),
  KEY `idx_chat_from` (`from_user_id`),
  KEY `idx_chat_to` (`to_user_id`),
  KEY `idx_chat_create_time` (`create_time`),
  KEY `idx_chat_conv_time` (`conversation_id`,`create_time`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='即时聊天消息表';
/*!40101 SET character_set_client = @saved_cs_client */;

